    { id = 7815, name = "Snapjaws, Mon!", level = 50, minLevel = 44, faction = "Horde", giver = "Katoom the Angler", start = { npc = "Katoom the Angler", area = 47, x = 80.3, y = 81.5 }, finish = { npc = "Katoom the Angler", area = 47, x = 80.3, y = 81.5 }, steps = { { name = "Saltwater Snapjaw", area = 47, x = 80.0, y = 63.5 } }, objective = "Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill 15 Saltwater Snapjaw turtles. Return to him when you have completed this task." },
    { id = 7816, name = "Gammerita, Mon!", level = 48, minLevel = 44, faction = "Horde", giver = "Katoom the Angler", start = { npc = "Katoom the Angler", area = 47, x = 80.3, y = 81.5 }, finish = { npc = "Katoom the Angler", area = 47, x = 80.3, y = 81.5 }, steps = { { name = "Katoom's Best Lure", area = 47, x = 80.4, y = 58.2 } }, objective = "Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill Gammerita and retrieve Katoom's Best Lure from her corpse.  Katoom mentioned that Gammerita hangs out on the coast with the other turtles." },
    { id = 7828, name = "Stalking the Stalkers", level = 48, minLevel = 44, faction = "Horde", giver = "Huntsman Markhor", start = { npc = "Huntsman Markhor", area = 47, x = 79.2, y = 79.5 }, finish = { npc = "Huntsman Markhor", area = 47, x = 79.2, y = 79.5 }, steps = { { name = "Silvermane Stalker", area = 47, x = 68.5, y = 54.3 }, { name = "Silvermane Howler", area = 47, x = 44.5, y = 59.2 } }, objective = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 10 Silvermane Stalkers and 10 Silvermane Howlers. Return to him once the task is complete.  Markhor mentioned that the wolves hide in the wilds of the Hinterlands." },
    { id = 7829, name = "Hunt the Savages", level = 48, minLevel = 44, faction = "Horde", giver = "Huntsman Markhor", start = { npc = "Huntsman Markhor", area = 47, x = 79.2, y = 79.5 }, finish = { npc = "Huntsman Markhor", area = 47, x = 79.2, y = 79.5 }, steps = { { name = "Savage Owlbeast", area = 47, x = 58.1, y = 50.4 } }, objective = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 20 Savage Owlbeasts. Return to him once the task is complete.  Markhor mentioned that the Savage Owlbeasts occupy the wilds of the Hinterlands." },
    { id = 7830, name = "Avenging the Fallen", level = 48, minLevel = 44, faction = "Horde", giver = "Huntsman Markhor", start = { npc = "Huntsman Markhor", area = 47, x = 79.2, y = 79.5 }, finish = { npc = "Huntsman Markhor", area = 47, x = 79.2, y = 79.5 }, steps = { { name = "Skylord Plume", area = 47, x = 58.3, y = 50.1 } }, objective = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill a Razorbeak Skylord and retrieve its Skylord Plume. Return to him once the task is complete.  Markhor mentioned that the Razorbeak Skylord are a rare breed that tend to occupy the wilds of the Hinterlands." },
    { id = 7839, name = "Vilebranch Hooligans", level = 48, minLevel = 44, faction = "Horde", giver = "Smith Slagtree", start = { npc = "Smith Slagtree", area = 47, x = 77.2, y = 80.1 }, finish = { npc = "Smith Slagtree", area = 47, x = 77.2, y = 80.1 }, steps = { { name = "Slagtree's Lost Tools", area = 47, x = 56.1, y = 41.3 } }, objective = "Smith Slagtree at Revantusk Village in the Hinterlands wants you to find Slagtree's Lost Tools. Return to him once this task is complete.  You recall Smith Slagtree mentioning that the tools might be at one of the Vilebranch temples in the northeastern region of the Hinterlands. You should also check Skulk Rock." },
    { id = 7840, name = "Lard Lost His Lunch", level = 49, minLevel = 44, faction = "Horde", giver = "Lard", start = { npc = "Lard", area = 47, x = 78.1, y = 81.4 }, finish = { npc = "Lard", area = 47, x = 78.1, y = 81.4 }, steps = { { name = "Lard's Lunch", area = 47, x = 84.5, y = 41.2 } }, objective = "Lard at Revantusk Village in the Hinterlands wants you to find Lard's Lunch. Return to him when this task is complete.  Lard mentioned that he left it on the island to the north. Watch out for Vilebranch trolls." },
    { id = 7841, name = "Message to the Wildhammer", level = 48, minLevel = 44, faction = "Horde", giver = "Otho Moji'ko", start = { npc = "Otho Moji'ko", area = 47, x = 79.4, y = 79.1 }, finish = { npc = "Otho Moji'ko", area = 47, x = 79.4, y = 79.1 }, steps = { { name = "Highvale Scout", area = 47, x = 32.1, y = 48.2 }, { name = "Highvale Outrunner", area = 47, x = 32.3, y = 48.7 }, { name = "Highvale Ranger", area = 47, x = 30.2, y = 46.4 }, { name = "Highvale Marksman", area = 47, x = 30.7, y = 46.6 } }, objective = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to slaughter 15 Highvale Outrunners, 15 Highvale Scouts, 15 Highvale Marksman and 15 Highvale Rangers. Return to him when this task is complete.  You can find the Highvale high elves at the Quel'Danil Lodge in the northwestern region of the Hinterlands." },
    { id = 7842, name = "Another Message to the Wildhammer", level = 48, minLevel = 44, requires = { 7841 }, faction = "Horde", giver = "Otho Moji'ko", start = { npc = "Otho Moji'ko", area = 47, x = 79.4, y = 79.1 }, finish = { npc = "Otho Moji'ko", area = 47, x = 79.4, y = 79.1 }, steps = { { name = "Long Elegant Feather", area = 47, x = 58.3, y = 50.1 } }, objective = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to bring him 10 Long Elegant Feathers from the gryphons that inhabit the Hinterlands. Return to him once this task is complete.  Gryphons are known to inhabit every region of the Hinterlands." },
    { id = 7843, name = "The Final Message to the Wildhammer", level = 50, minLevel = 44, requires = { 7842 }, faction = "Horde", giver = "Otho Moji'ko", start = { npc = "Otho Moji'ko", area = 47, x = 79.4, y = 79.1 }, finish = { npc = "Otho Moji'ko", area = 47, x = 79.4, y = 79.1 }, steps = { { name = "Message to the Wildhammer Delivered", area = 47, x = 14.3, y = 48.1 } }, objective = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to travel to Aerie Peak in the western region of the Hinterlands and place the Final Message to the Wildhammer by the well in the center of town. Return to him once this task is complete.  Beware of angry Wildhammer dwarves and unruly members of the Alliance." },
    { id = 7844, name = "Cannibalistic Cousins", level = 48, minLevel = 44, faction = "Horde", giver = "Mystic Yayo'jin", start = { npc = "Mystic Yayo'jin", area = 47, x = 78.8, y = 78.3 }, finish = { npc = "Mystic Yayo'jin", area = 47, x = 78.8, y = 78.3 }, steps = { { name = "Vilebranch Scalper", area = 47, x = 69.3, y = 46.7 }, { name = "Vilebranch Soothsayer", area = 47, x = 47.6, y = 66.4 } }, objective = "Mystic Yayo'jin at Revantusk Village in the Hinterlands wants you to kill 30 Vilebranch Scalpers and 15 Vilebranch Soothsayers. Return to her when this task is complete.  Yayo'jin indicated that these trolls could be found near the Shaol'watha and Agol'watha temples in the north by northeastern region of the Hinterlands." },
    { id = 7845, name = "Kidnapped Elder Torntusk!", level = 51, minLevel = 46, faction = "Horde", giver = "Primal Torntusk", start = { npc = "Primal Torntusk", area = 47, x = 78.2, y = 81.2 }, finish = { npc = "Elder Torntusk", area = 47, x = 59.7, y = 77.8 }, objective = "Primal Torntusk at Revantusk Village in the Hinterlands wants you to rescue her mate, Elder Torntusk, from Jintha'alor.  You have been told that he is being held prisoner atop Jintha'alor, the Vilebranch capital city located in the southern region of the Hinterlands." },
    { id = 7846, name = "Recover the Key!", level = 51, minLevel = 46, requires = { 7845 }, faction = "Horde", giver = "Elder Torntusk", start = { npc = "Elder Torntusk", area = 47, x = 59.7, y = 77.8 }, finish = { npc = "Elder Torntusk", area = 47, x = 59.7, y = 77.8 }, steps = { { name = "Shackle Key", area = 47, x = 57.3, y = 86.6 } }, objective = "Elder Torntusk at Jintha'alor wants you to kill Hitah'ya the Keeper to get the Shackle Key to his bindings. Return to Elder Torntusk when you have recovered the key." },
    { id = 7847, name = "Return to Primal Torntusk", level = 51, minLevel = 46, requires = { 7846 }, faction = "Horde", giver = "Elder Torntusk", start = { npc = "Elder Torntusk", area = 47, x = 59.7, y = 77.8 }, finish = { npc = "Primal Torntusk", area = 47, x = 78.2, y = 81.2 }, objective = "Elder Torntusk at Jintha'alor wants you to return to Primal Torntusk at Revantusk Village with news of his rescue." },
    { id = 7849, name = "Separation Anxiety", level = 50, minLevel = 46, faction = "Horde", giver = "Huntsman Markhor", start = { npc = "Huntsman Markhor", area = 47, x = 79.2, y = 79.5 }, finish = { npc = "Huntsman Markhor", area = 47, x = 79.2, y = 79.5 }, steps = { { name = "Huntsman Malkhor's Skull", area = 47, x = 58.6, y = 64.8 }, { name = "Huntsman Malkhor's Bones", area = 47, x = 62.1, y = 75.4 } }, objective = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor.  Markhor mentioned that his brother's remains were fed to the oozes and wolves of the Vilebranch. He also mentioned that there is a refuse pit filled with oozes in Jintha'alor as well as a wolf den. Both of these places are near the top of the temple." },
    { id = 7850, name = "Dark Vessels", level = 50, minLevel = 46, faction = "Horde", giver = "Primal Torntusk", start = { npc = "Primal Torntusk", area = 47, x = 78.2, y = 81.2 }, finish = { npc = "Primal Torntusk", area = 47, x = 78.2, y = 81.2 }, steps = { { name = "Vessel of Tainted Blood", area = 47, x = 63.8, y = 73.8 } }, objective = "Primal Torntusk at Revantusk Village in the Hinterlands wants you to recover 10 Vessels of Tainted Blood from Jintha'alor. Return to Primal Torntusk when this task is complete." },
    { id = 7861, name = "Wanted: Vile Priestess Hexx and Her Minions", level = 51, minLevel = 46, faction = "Horde", finish = { npc = "Primal Torntusk", area = 47, x = 78.2, y = 81.2 }, steps = { { name = "Vile Priestess Hexx", area = 47, x = 59.5, y = 78.3 }, { name = "Vilebranch Aman'zasi Guard", area = 47, x = 58.0, y = 82.2 } }, objective = "You have been ordered to slay Vile Priestess Hexx and 20 Vilebranch Aman'zasi Guards. See Primal Torntusk at Revantusk Village in the Hinterlands once this task is complete.  Vile Priestess Hexx and the Aman'zasi Guards can be found atop Jintha'alor in the Hinterlands." },
    { id = 7862, name = "Job Opening: Guard Captain of Revantusk Village", level = 51, minLevel = 46, faction = "Horde", finish = { npc = "Primal Torntusk", area = 47, x = 78.2, y = 81.2 }, steps = { { name = "Vilebranch Berserker", area = 47, x = 65.3, y = 70.7 }, { name = "Vilebranch Shadow Hunter", area = 47, x = 63.6, y = 71.9 }, { name = "Vilebranch Blood Drinker", area = 47, x = 63.2, y = 76.4 }, { name = "Vilebranch Soul Eater", area = 47, x = 62.3, y = 75.5 } }, objective = "You have been tasked with the decimation of 20 Vilebranch Berserkers, 20 Vilebranch Shadow Hunters, 20 Vilebranch Blood Drinkers, and 20 Vilebranch Soul Eaters.  Should you complete this task, return to Primal Torntusk at Revantusk Village in the Hinterlands." },
    { id = 8273, name = "Oran's Gratitude", level = 47, minLevel = 42, requires = { 2782 }, faction = "Horde", giver = "Oran Snakewrithe", start = { npc = "Oran Snakewrithe", area = 1497, x = 73.1, y = 32.9 }, finish = { npc = "Oran Snakewrithe", area = 1497, x = 73.1, y = 32.9 } },
