    { id = 4972, name = "Counting Out Time (1/2)", level = 56, minLevel = 53, requires = { 4971 }, giver = "Chromie", start = { npc = "Chromie", area = 28, x = 39.5, y = 66.8 }, finish = { npc = "Chromie", area = 28, x = 39.5, y = 66.8 }, steps = { { name = "Andorhal Watch", area = 28, x = 43.0, y = 70.1 } }, objective = "Locate 5 Andorhal Watches, found in lockboxes amongst the rubble of the city. Return with them to Chromie in the Andorhal Inn, Western Plaguelands." },
