    { id = 4985, name = "The Wildlife Suffers Too (2/2)", level = 56, minLevel = 51, requires = { 4984 }, giver = "Mulgris Deepriver", start = { npc = "Mulgris Deepriver", area = 28, x = 53.7, y = 64.7 }, finish = { npc = "Mulgris Deepriver", area = 28, x = 53.7, y = 64.7 }, steps = { { name = "Diseased Grizzly", area = 28, x = 61.4, y = 51.2 } }, objective = "Destroy 8 Diseased Grizzlies, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands." },
    { id = 4986, name = "Glyphed Oaken Branch", level = 56, minLevel = 51, requires = { 4985 }, faction = "Alliance", giver = "Mulgris Deepriver", start = { npc = "Mulgris Deepriver", area = 28, x = 53.7, y = 64.7 }, finish = { npc = "Mathrengyl Bearwalker", area = 1657, x = 35.4, y = 8.4 }, objective = "Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Darnassus is the next step the tauren druid sought. Seek one of the druids there for assistance." },
    { id = 4987, name = "Glyphed Oaken Branch", level = 56, minLevel = 51, requires = { 4985 }, faction = "Horde", giver = "Mulgris Deepriver", start = { npc = "Mulgris Deepriver", area = 28, x = 53.7, y = 64.7 }, finish = { npc = "Nara Wildmane", area = 1638, x = 75.7, y = 31.6 }, objective = "Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Thunder Bluff is the next step the tauren druid sought. Seek one of the druids there for assistance." },
    { id = 5021, name = "Better Late Than Never", level = 52, minLevel = 50, giver = "Janice Felstone", start = { npc = "Janice Felstone", area = 28, x = 38.4, y = 54.1 }, objective = "The ramblings of the ghostly woman indicated that she needed a package delivered. She claimed that it was where her horse was. As to where the horse is or where the package was to be delivered - the ghost remains incomprehensible." },
    { id = 5022, name = "Better Late Than Never", level = 52, minLevel = 50, requires = { 5021 }, faction = "Alliance", finish = { npc = "Royal Factor Bathrilor", area = 1519, x = 57.2, y = 48.1 }, objective = "Check with the Royal Factors of Stormwind to learn the whereabouts of an Emma Felstone. There is usually a census officer located in City Hall." },
    { id = 5023, name = "Better Late Than Never", level = 52, minLevel = 50, requires = { 5021 }, faction = "Horde", finish = { npc = "Royal Overseer Bauhaus", area = 1497, x = 69.8, y = 43.2 }, objective = "Check with the Royal Overseers of the Undercity to learn the whereabouts of a Jeremiah Felstone. There is usually a census officer located near guild and tabard registration." },
    { id = 5050, name = "Good Luck Charm", level = 52, minLevel = 50, requiresAny = { 5048, 5049 }, giver = "Ol' Emma", start = { npc = "Ol' Emma", area = 1519, x = 60.2, y = 57.0 }, finish = { npc = "Janice Felstone", area = 28, x = 38.4, y = 54.1 }, objective = "Return to Janice Felstone in Western Plaguelands her Good Luck Half-Charm." },
    { id = 5051, name = "Two Halves Become One", level = 54, minLevel = 50, requires = { 5050 }, giver = "Janice Felstone", start = { npc = "Janice Felstone", area = 28, x = 38.4, y = 54.1 }, finish = { npc = "Janice Felstone", area = 28, x = 38.4, y = 54.1 }, objective = "Locate the other half of the Good Luck Charm somewhere on the Felstone Farm in Western Plaguelands and reassemble it.  Give the Good Luck Charm to Janice Felstone on the Felstone Farm, Western Plaguelands." },
