    { id = 8304, name = "Dearest Natalia", level = 60, minLevel = 58, giver = "Commander Mar'alith", start = { npc = "Commander Mar'alith", area = 1377, x = 49.2, y = 34.2 }, finish = { npc = "Commander Mar'alith", area = 1377, x = 49.2, y = 34.2 }, steps = { { name = "Frankal Stonebridge", area = 1377, x = 40.8, y = 88.9 }, { name = "Rutgar Glyphshaper", area = 1377, x = 41.3, y = 88.5 } }, objective = "Commander Mar'alith at Cenarion Hold in Silithus wants you to question the inhabitants of Bronzebeard's Encampment. You will find Bronzebeard's Encampment south of Cenarion Hold.  Once you have gathered the requested information, return to Commander Mar'alith." },
    { id = 8305, name = "Long Forgotten Memories", level = 60, minLevel = 60, requires = { 8303 }, giver = "Anachronos", start = { npc = "Anachronos", area = 440, x = 65.3, y = 50.0 }, objective = "Locate the Crystalline Tear in Silithus and gaze into its depths." },
    { id = 8306, name = "Into The Maw of Madness", level = 60, minLevel = 58, requires = { 8304 }, giver = "Commander Mar'alith", start = { npc = "Commander Mar'alith", area = 1377, x = 49.2, y = 34.2 }, finish = { npc = "Commander Mar'alith", area = 1377, x = 49.2, y = 34.2 }, steps = { { name = "The Fate of Mistress Natalia Mar'alith", area = 10073, x = 44.4, y = 86.1 } }, objective = "Commander Mar'alith at Cenarion Hold in Silithus wants you to find his beloved Natalia. The information that you gathered points to Hive'Regal in the south as being the area in which you may find Mistress Natalia Mar'alith.  Do not forget to visit the dwarves at Bronzebeard's camp before venturing into the hive. They might have some additional work and advice for you.  And <Name>, remember the Commander's words: \"Do what you must...\"" },
    { id = 8308, name = "Brann Bronzebeard's Lost Letter", level = 60, minLevel = 58, finish = { npc = "Rutgar Glyphshaper", area = 1377, x = 41.3, y = 88.5 }, objective = "Take Brann Bronzebeard's Letter to Bronzebeard's Encampment in southern Silithus." },
    { id = 8309, name = "Glyph Chasing", level = 60, minLevel = 58, requires = { 8304 }, giver = "Rutgar Glyphshaper", start = { npc = "Rutgar Glyphshaper", area = 1377, x = 41.3, y = 88.5 }, finish = { npc = "Rutgar Glyphshaper", area = 1377, x = 41.3, y = 88.5 }, steps = { { name = "Hive'Ashi Rubbing", area = 1377, x = 50.9, y = 26.8 }, { name = "Hive'Zora Rubbing", area = 1377, x = 37.3, y = 62.5 }, { name = "Hive'Regal Rubbing", area = 10073, x = 44.4, y = 86.1 } }, objective = "Rutgar Glyphshaper at Bronzebeard's Encampment in Silithus wants you to venture to Hive'Ashi, Hive'Zora, and Hive'Regal and recover Glyphed Rubbings from the Glyphed Crystals of each hive.  Use the Geologist's Transcription Kit to make a reasonable facsimile of the ancient glyphs. Return to Rutgar Glyphshaper when you complete this task." },
    { id = 8310, name = "Breaking the Code", level = 60, minLevel = 58, requires = { 8304 }, giver = "Frankal Stonebridge", start = { npc = "Frankal Stonebridge", area = 1377, x = 40.8, y = 88.9 }, finish = { npc = "Frankal Stonebridge", area = 1377, x = 40.8, y = 88.9 }, steps = { { name = "Hive'Ashi Silithid Brain", area = 1377, x = 44.4, y = 21.0 }, { name = "Hive'Zora Silithid Brain", area = 1377, x = 25.4, y = 63.2 }, { name = "Hive'Regal Silithid Brain", area = 1377, x = 58.1, y = 80.2 } }, objective = "Frankal Stonebridge at Bronzebeard's Encampment in Silithus wants you to recover a Hive'Zora Silithid Brain, Hive'Ashi Silithid Brain, and a Hive'Regal Silithid Brain. Return to Frankal when you have completed this task." },
