    { id = 8315, name = "The Calling", level = 60, minLevel = 58, requires = { 8314 }, giver = "Geologist Larksbane", start = { npc = "Geologist Larksbane", area = 1377, x = 49.7, y = 37.5 }, finish = { npc = "Geologist Larksbane", area = 1377, x = 49.7, y = 37.5 }, steps = { { name = "Crystal Unlocking Mechanism", area = 1377, x = 48.8, y = 58.1 } }, objective = "Geologist Larksbane at Cenarion Hold in Silithus wants you to recover the Crystal Unlocking Mechanism from the Qiraji Emissary.  You have been instructed to take the Glyphs of Calling to the Bones of Grakkarond, south of Cenarion Hold, and draw them in the sand. Should the Qiraji Emissary appear, slay it and recover the Crystal Unlocking Mechanism. Return to Geologist Larksbane if you succeed.  Assemble an army for this task, <Name>!" },
